insert into public.profesionales (slug, nombre, cargo, bio, num_colegiado, sanitario) values
('rosa-ondono', 'Rosa Ondoño', 'Fundadora · esteticista y terapeuta', 'Más de 30 años de oficio. Empezó en el Hotel Sidi San Juan y se formó en Llongueras (Barcelona) y en naturopatía y terapias manuales en Madrid. Médicos de Alicante, Madrid y Barcelona le han confiado durante años a sus pacientes para el drenaje postquirúrgico.', null, false),
('dr-roberth-bravo-pardo', 'Dr. Roberth Bravo Pardo', 'Médico estético y nutricionista', 'Responsable de la medicina estética del centro. Cada tratamiento médico empieza con una consulta en la que valora tu caso, te explica opciones, riesgos y alternativas, y decide contigo si está indicado.', null, true);
insert into public.tratamientos (slug, nombre, categoria_slug, pilar_slug, programa_slug, tipo, profesional_slug, prioridad, destacado, resumen, revision_pendiente, reservable, sesiones) values
('valoracion-integral', 'Valoración integral', 'valoracion', 'cuidate', null, 'estetica', 'rosa-ondono', 1, true, 'Empieza por aquí. Hablamos de lo que te gustaría mejorar, analizamos piel, cuerpo y hábitos, y te llevas un plan personalizado por escrito.', null, true, 'Orientativo: se concreta en tu valoración'),
('limpieza-facial-profunda', 'Limpieza facial profunda', 'faciales', 'cuidate', 'rejuvenecimiento-facial', 'estetica', 'rosa-ondono', 1, true, 'Limpieza en profundidad adaptada a tu tipo de piel, con extracción cuidadosa, mascarilla e hidratación final.', null, true, 'Orientativo: se concreta en tu valoración'),
('tratamiento-facial-antiedad', 'Tratamiento facial antiedad', 'faciales', 'cuidate', 'rejuvenecimiento-facial', 'estetica', 'rosa-ondono', 2, false, 'Protocolo de cabina para una piel más luminosa y con mejor aspecto, combinando activos y técnicas según tu piel.', null, true, 'Orientativo: se concreta en tu valoración'),
